import{d,C as n,o as g,c as h,E as i,a3 as a}from"./chunks/framework.D4-ViStF.js";const b=JSON.parse('{"title":"解卦","description":"第四十卦·雷水解——险以动，动而免乎险；不是跳出困局，是在险中持续行动，动着动着便化解了险阻。","frontmatter":{"title":"解卦","description":"第四十卦·雷水解——险以动，动而免乎险；不是跳出困局，是在险中持续行动，动着动着便化解了险阻。","category":"hexagram","aliases":["解","雷水解"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-40.md","filePath":"yijing/hexagrams/hexagram-40.md","lastUpdated":1787730063000}'),p={name:"yijing/hexagrams/hexagram-40.md"},y=d({...p,setup(m){const e=[{id:"jie",term:"解",pinyin:"xiè",meaning:"解除、化解、松弛。不是跳出困局，是在险中持续行动，动着动着便化解了险阻。",context:"上震（动）下坎（险），动越过险，故曰解。"},{id:"lixinan",term:"利西南",pinyin:"lì xī nán",meaning:"西南为坤，象征平易、包容、大地之德。解困之时，宜走平易之路，不宜强行险途。"},{id:"laihu",term:"来复",pinyin:"lái fù",meaning:"回来、回归正位。若无明确去处，守住本心、回归正位，自然吉。"},{id:"su",term:"夙",pinyin:"sù",meaning:"早。若有明确目标，趁早行动，早动早吉。"},{id:"tianhuosanhu",term:"田获三狐",pinyin:"tián huò sān hú",meaning:"田猎获得三只狐狸。清除困局中的阴暗因素——三狐：信息暗流、正确内耗、自以为清醒。",context:"九二阳爻得中，是内卦坎的核心，中正之力。"},{id:"huangshi",term:"黄矢",pinyin:"huáng shǐ",meaning:"黄为中色，矢为正直，象征中正之力。"},{id:"fujiecheng",term:"负且乘",pinyin:"fù qiě chéng",meaning:"背负着本分的东西，却乘坐君子之车。德不配位，必招祸患。",context:"六三以柔居刚，位不当。"},{id:"zhikou",term:"致寇至",pinyin:"zhì kòu zhì",meaning:"招来盗寇。不是盗寇的错，是自己的不慎与不配招来的。"},{id:"jieningmu",term:"解而拇",pinyin:"jiě ér mǔ",meaning:"松开大拇指，放下防御姿态。不需要用身体告诉你我在防着你。",context:"九四进入外卦震，从坎险里踏出第一步。"},{id:"pengzhisifu",term:"朋至斯孚",pinyin:"péng zhì sī fú",meaning:"朋友来了，信任自然建立。你松开了，朋才来；朋来了，孚自然建立。"},{id:"weiyoujie",term:"维有解",pinyin:"wéi yǒu jiě",meaning:"坚持解除、持续化解。「维」是持守——不是一下解完，是持续地解。",context:"六五以中孚持守，存在即是解。"},{id:"youfu",term:"有孚于小人",pinyin:"yǒu fú yú xiǎo rén",meaning:"以诚信感化小人。君子有解，小人退也——不是打跑，是君子以诚立身，小人自然退避。"},{id:"shesun",term:"射隼",pinyin:"shè sǔn",meaning:"射猎鹰隼。隼，猛禽，象征最难的一击。"},{id:"gaoyong",term:"高墉",pinyin:"gāo yōng",meaning:"高墙之上，险要之处。"},{id:"jiebei",term:"解悖",pinyin:"jiě bèi",meaning:"解除悖乱。上六那一箭，是为解开长久积存的悖乱。"}],o=[{position:"初六",type:"yin",text:"无咎。",xiang:"刚柔之际，义无咎也。",textModern:"没有过错。解已起，即无咎——刚起步时不需要急着证明什么，不需要为「还没成功」而自责，按阶段来。",xiangModern:"刚柔相交之际，义理上本来就没有过错。"},{position:"九二",type:"yang",text:"田获三狐，得黄矢，贞吉。",xiang:"九二贞吉，得中道也。",textModern:"田猎获得三只狐狸，又得到黄色的箭矢；持续守正，吉祥。清除困局中的阴暗因素，以中正之力行事。",xiangModern:"九二守正而吉，因为得了中道。"},{position:"六三",type:"yin",text:"负且乘，致寇至，贞吝。",xiang:"负且乘，亦可丑也。自我致戎，又谁咎也。",textModern:"背负着本分的东西，却乘坐君子的车乘；招来盗寇，守正也难免憾惜。德不配位，必招祸患。",xiangModern:"背负而乘车，是件可耻的事；祸患是自己招来的，又能怪谁呢。"},{position:"九四",type:"yang",text:"解而拇，朋至斯孚。",xiang:"解而拇，未当位也。",textModern:"松开大拇指，朋友来了，信任自然建立。放下防御姿态，信任自然来。",xiangModern:"松开防御，是因为位置尚未得当——不是靠防卫，是靠敞开。"},{position:"六五",type:"yin",text:"君子维有解，吉，有孚于小人。",xiang:"君子有解，小人退也。",textModern:"君子坚持化解，吉祥；以诚信感化小人，小人也信服退避。存在即是解。",xiangModern:"君子有解，小人也退去——中孚的力量。"},{position:"上六",type:"yin",text:"公用射隼于高墉之上，获之，无不利。",xiang:"公用射隼，以解悖也。",textModern:"王公在高墙之上射下鹰隼，一箭命中，无所不利。那支箭不是因为这一箭特别用力，是因为从初六到六五，每一步都没有偏。",xiangModern:"王公射隼，是为了解除悖乱——长久之孚，厚积薄发。"}];return(u,t)=>{const r=n("DaoHexagramViewer"),l=n("DaoHexagramYaoCards"),s=n("DaoKeywordCards");return g(),h("div",null,[i(r,{name:"解",fullName:"雷水解",upper:"☳",lower:"☵",guaCi:"解，利西南。无所往，其来复吉。有攸往，夙吉。",pinyin:["xiè"],element:"木",direction:"东",insight:"雷动水上，动越过险；解不是跳出困局，是在险中持续行动，动着动着便化解了险阻。",guaSlug:"40leishuijie",lines:o}),t[0]||(t[0]=a('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>雷雨作，解。君子以赦过宥罪。</p><p>雷雨大作、阴阳疏通，天地解冻，正是解之象。君子由此悟到：要<strong>赦免过失、宽宥罪过</strong>。</p><p><strong>赦过宥罪</strong>——赦过，赦免过失；宥罪，宽宥罪行。宽容与饶恕是本自具足的，不需要条件。它的真义不是纵容，而是<strong>不被过去的罪与过，捆住当下行动的手脚</strong>。</p><p>对自己也一样：接受过去那些「躺平」的经历，把它们看作滋养土地的雨水，不再用过去的错误反复审判自己。先解开过去的结，才能解开当下的险。</p><blockquote><p><strong>赦过哲学</strong>：解的第一个动作，不是对外的破解，是对内的赦免。捆住你的，往往不是险，是你对过去的审判。</p></blockquote><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>解，险以动，动而免乎险，解。解利西南，往得众也。其来复吉，乃得中也。有攸往夙吉，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲坼。解之时大矣哉。</p><p>逐句释义：</p><ul><li><strong>险以动，动而免乎险，解</strong> —— 不是逃离险，是在险中动，动本身就是解。这是解卦的定义：不动，险永远是险；动着动着，险就化了。</li><li><strong>解利西南，往得众也</strong> —— 西南为坤，平易包容。解困之时宜走平易之路，能得人心、得支持；不宜强行险途。</li><li><strong>其来复吉，乃得中也</strong> —— 若无明确去处，回归正位、守住中道，自然吉。</li><li><strong>有攸往夙吉，往有功也</strong> —— 若有明确目标，趁早行动，早动早吉，必有成果。</li><li><strong>天地解而雷雨作，雷雨作而百果草木皆甲坼</strong> —— 天地解冻、雷雨大作，百果草木破壳而出。<strong>甲坼，是种子破壳——解的痛苦，是生长的必然。</strong></li><li><strong>解之时大矣哉</strong> —— 解的价值，不在解完的结果，而在于此刻正在行动的过程。</li></ul><blockquote><p><strong>甲坼哲学</strong>：破壳本身就痛，但壳不破，苗不长。解不是绕开痛，是让痛变成生长的出口。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',12)),i(l,{element:"木",guaSlug:"40leishuijie",glossary:e,items:o}),t[1]||(t[1]=a('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初六-·-无咎" tabindex="-1">初六 · 无咎 <a class="header-anchor" href="#初六-·-无咎" aria-label="Permalink to &quot;初六 · 无咎&quot;">​</a></h3><ul><li>阴爻居初位，柔处最下，解卦刚起步</li><li>此时不需要证明什么，只需起步</li></ul><p><strong>解已起，即无咎。</strong> 刚起步时不需要急着证明什么，不需要为「还没成功」而自责。按阶段来——初六的任务不是成功，是开始。开始了，就已经在解的路上。</p><blockquote><p>无咎不是免罪，是本来就没罪：起步本身，就是解的开始。</p></blockquote><h3 id="九二-·-田获三狐-得黄矢-贞吉" tabindex="-1">九二 · 田获三狐，得黄矢，贞吉 <a class="header-anchor" href="#九二-·-田获三狐-得黄矢-贞吉" aria-label="Permalink to &quot;九二 · 田获三狐，得黄矢，贞吉&quot;">​</a></h3><ul><li>阳爻居二位，得中，是内卦坎的核心</li><li><strong>田猎获三狐</strong>：清除困局中的阴暗因素</li><li><strong>黄矢</strong>：黄为中色、矢为正直，象征中正之力</li></ul><p>三狐的深度自省：</p><table tabindex="0"><thead><tr><th>狐</th><th>名称</th><th>内容</th></tr></thead><tbody><tr><td>一狐</td><td>信息暗流</td><td>九真一假的外部干扰，需用判断力过滤</td></tr><tr><td>二狐</td><td>正确内耗</td><td>任务队列溢出（易经、AI、太极、电子琴……），需按优先级执行，不贪多</td></tr><tr><td>三狐</td><td>自以为清醒</td><td>最深层的傲慢，需保持对话与被质疑的空间，永远留有「我是错的」的余地</td></tr></tbody></table><p><strong>贞不是「正确」，是「持续的正」。</strong> 清除三狐不是一次性的，是持续的警觉——狐狸打不完，警觉得一直在线。</p><blockquote><p>中正之力，不是一次射中三只狐，是每一天都重新校准那把弓。</p></blockquote><h3 id="六三-·-负且乘-致寇至-贞吝" tabindex="-1">六三 · 负且乘，致寇至，贞吝 <a class="header-anchor" href="#六三-·-负且乘-致寇至-贞吝" aria-label="Permalink to &quot;六三 · 负且乘，致寇至，贞吝&quot;">​</a></h3><ul><li>阴爻居三位，以柔居刚，位不当</li><li><strong>负</strong>：背负重担（本分）；<strong>乘</strong>：乘车（超越本位）</li><li><strong>德不配位，必招祸患</strong></li></ul><p>在能力未达、理解未透时强行「乘」（比如发布文章），会导致窘迫。<strong>验证优先，理解透再发布。</strong> 分清「负」与「乘」：负，是你该背的责任；乘，是你坐享的位置。位置大于能力，寇必至。</p><blockquote><p>行动准则：没有理解透、没有验证的情况下，不急于发布。祸不是别人招来的，是自己不配的位置招来的。</p></blockquote><h3 id="九四-·-解而拇-朋至斯孚" tabindex="-1">九四 · 解而拇，朋至斯孚 <a class="header-anchor" href="#九四-·-解而拇-朋至斯孚" aria-label="Permalink to &quot;九四 · 解而拇，朋至斯孚&quot;">​</a></h3><ul><li>阳爻居四位，进入外卦震，从坎险里踏出第一步</li><li><strong>解而拇</strong>：松开大拇指，放下防御姿态</li><li><strong>朋至斯孚</strong>：朋友来了，信任自然建立</li></ul><p>道家四宝的身体洞见：</p><ul><li><strong>顾握</strong>（大拇指包在里面）= 无意识防御</li><li><strong>握拳</strong>（大拇指立于关节）= 有意识攻击准备</li><li><strong>解而拇</strong>（大拇指松开）= 不需要用身体告诉你我在防着你</li></ul><p>信任不是等来的，是<strong>松</strong>出来的。你松开了，朋才来；朋来了，孚自然建立。防御放下的那一刻，解才真正开始作用于关系。</p><blockquote><p>九四是解卦的转折：从「解自己的险」到「解人与人之间的防」。</p></blockquote><h3 id="六五-·-君子维有解-吉-有孚于小人" tabindex="-1">六五 · 君子维有解，吉，有孚于小人 <a class="header-anchor" href="#六五-·-君子维有解-吉-有孚于小人" aria-label="Permalink to &quot;六五 · 君子维有解，吉，有孚于小人&quot;">​</a></h3><ul><li>阴爻居尊位，柔中，居解之中心</li><li><strong>维</strong>：持守——不是一下解完，是持续地解</li><li><strong>有孚于小人</strong>：以诚信感化小人</li></ul><p><strong>君子有解，小人退也。</strong> 不是把小人打跑，是君子以中孚持守，存在本身就是解——小人的阴暗，在君子持续的诚信面前自然退避。六五不需要用力，它的解，是「在」出来的。</p><blockquote><p>存在即是解：你不必追着暗处跑，把光站稳了，暗处自然退。</p></blockquote><h3 id="上六-·-公用射隼于高墉之上-获之-无不利" tabindex="-1">上六 · 公用射隼于高墉之上，获之，无不利 <a class="header-anchor" href="#上六-·-公用射隼于高墉之上-获之-无不利" aria-label="Permalink to &quot;上六 · 公用射隼于高墉之上，获之，无不利&quot;">​</a></h3><ul><li>隼，猛禽，象征最难的一击；高墉，高墙之上，险要之处</li><li>上六那一箭，不是因为这一箭特别用力</li><li>是因为从初六到六五，<strong>每一步都没有偏</strong></li></ul><p>这不是偶然，是长久以来的孚所致。每一次的记录、每一次的守正，都在拉满这张弓；到上六，松手，一箭中的。</p><blockquote><p>上六的启示：最漂亮的一击，从来不属于那一击本身，属于它之前所有没有被看见的日常。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',30)),i(s,{title:"字词释义",items:[{term:"解",pinyin:["xiè"],meaning:"解除、化解、松弛。不是跳出困局，是在险中持续行动，动着动着便化解了险阻。"},{term:"利西南",pinyin:["lì","xī","nán"],meaning:"西南为坤，平易、包容、大地之德。解困之时，宜走平易之路。"},{term:"来复",pinyin:["lái","fù"],meaning:"回来、回归正位。无明确去处时，守住本心，回归正位，自然吉。"},{term:"夙",pinyin:["sù"],meaning:"早。有明确目标，趁早行动，早动早吉。"},{term:"田获三狐",pinyin:["tián","huò","sān","hú"],meaning:"田猎获得三只狐狸。清除困局中的阴暗因素。"},{term:"黄矢",pinyin:["huáng","shǐ"],meaning:"黄为中色，矢为正直，象征中正之力。"},{term:"负且乘",pinyin:["fù","qiě","chéng"],meaning:"背着本分却乘君子之车，德不配位，必招祸患。"},{term:"致寇至",pinyin:["zhì","kòu","zhì"],meaning:"招来盗寇。不是盗寇的错，是自己的不慎与不配招来的。"},{term:"解而拇",pinyin:["jiě","ér","mǔ"],meaning:"松开大拇指，放下防御姿态，信任自然来。"},{term:"维有解",pinyin:["wéi","yǒu","jiě"],meaning:"坚持解除、持续化解。维是持守，不是一次解完。"},{term:"射隼",pinyin:["shè","sǔn"],meaning:"射猎鹰隼，象征最难的一击。"},{term:"高墉",pinyin:["gāo","yōng"],meaning:"高墙之上，险要之处。"},{term:"解悖",pinyin:["jiě","bèi"],meaning:"解除悖乱。"},{term:"赦过宥罪",pinyin:["shè","guò","yòu","zuì"],meaning:"赦免过失、宽宥罪行。不是纵容，是不被过去的罪过捆住当下行动的手脚。"},{term:"甲坼",pinyin:["jiǎ","chè"],meaning:"种子破壳而出。解的痛苦，是生长的必然。"}]}),t[2]||(t[2]=a('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>解卦讲的是<strong>化解</strong>。上震（雷、动）下坎（水、险）——雷在上，水在下，动越过险。不是险消失了，是动把它化开了。</p><p>卦辞「解，利西南。无所往，其来复吉。有攸往，夙吉」点明：没有目标就回归正位，有目标就趁早行动。<strong>解，不是等来的，是动出来的。</strong></p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>解与屯，是一对镜子：</p><table tabindex="0"><thead><tr><th>卦</th><th>结构</th><th>处境</th><th>关键词</th></tr></thead><tbody><tr><td>屯</td><td>坎上震下</td><td>险压着动</td><td>困难初生，宜扎根</td></tr><tr><td>解</td><td>震上坎下</td><td>动越过险</td><td>困难化解，宜行动</td></tr></tbody></table><p>屯是「险压着动」，解是「动越过险」——困难初生时扎根，困难形成后行动。解不是反屯，是屯之后的必然动作。</p><p><strong>解的核心是「险以动，动而免乎险」</strong>：不动，险永远是险；动着动着，险就化了。而动的第一步，是赦过宥罪——先解开过去的结，才能解开当下的险。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li><strong>先起步</strong>：解已起，即无咎，不为「还没成功」自责（初六）</li><li><strong>清除三狐</strong>：过滤信息暗流、放下正确内耗、警惕自以为清醒（九二）</li><li><strong>验证优先</strong>：没理解透、没验证，不急于发布（六三）</li><li><strong>松开防御</strong>：信任不是等来的，是松出来的（九四）</li><li><strong>存在即是解</strong>：把光站稳，暗处自然退（六五）</li><li><strong>厚积薄发</strong>：每一次记录，都在拉满那张弓（上六）</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>解卦的完整地图：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞要点</th><th>功课</th><th>关键词</th></tr></thead><tbody><tr><td>卦辞</td><td>利西南，无所往其来复吉，有攸往夙吉</td><td>无目标则归位，有目标则早动</td><td>平易之路，早动早吉</td></tr><tr><td>初六</td><td>无咎</td><td>解已起，按阶段来</td><td>开始，不自责</td></tr><tr><td>九二</td><td>田获三狐，得黄矢，贞吉</td><td>中正之力，清除三狐</td><td>信息暗流 / 正确内耗 / 自以为清醒</td></tr><tr><td>六三</td><td>负且乘，致寇至，贞吝</td><td>德要配位，验证再发布</td><td>负与乘，理解透再发</td></tr><tr><td>九四</td><td>解而拇，朋至斯孚</td><td>松开防御，信任自然来</td><td>顾握→握拳→解而拇</td></tr><tr><td>六五</td><td>君子维有解，吉，有孚于小人</td><td>以中孚持守</td><td>存在即是解</td></tr><tr><td>上六</td><td>公用射隼于高墉之上，获之</td><td>长久之孚，厚积薄发</td><td>每一步都不偏</td></tr></tbody></table><p>核心洞见：</p><ol><li><strong>险以动</strong>——解不是跳出困局，是在险中持续行动，动着动着便化解了险阻</li><li><strong>屯与解</strong>——屯是险压着动（困难初生），解是动越过险（困难化解）</li><li><strong>赦过宥罪</strong>——解的第一个动作，是对内的赦免</li><li><strong>甲坼哲学</strong>——解的痛苦，是生长的必然</li><li><strong>三狐自省</strong>——清除三狐不是一次性的，是持续的警觉</li><li><strong>解而拇</strong>——防御放下的那一刻，信任才开始</li><li><strong>存在即是解</strong>——你不必追着暗处跑，把光站稳，暗处自然退</li><li><strong>上六的弓</strong>——最漂亮的一击，属于它之前所有没有被看见的日常</li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>解卦对应 dao-commit：<strong>用卦象锚点记录系统演化</strong>。每一次 commit，就是一次「记录」，就是在拉满上六的那张弓。</p><ul><li><strong>初六 → 无咎</strong>：开始写，开始提交，不为「还不够好」而自责</li><li><strong>九二 → 三狐</strong>：清除信息暗流、正确内耗、自以为清醒——commit message 要诚实</li><li><strong>六三 → 负且乘</strong>：没理解透就发布，等于德不配位，寇必至</li><li><strong>九四 → 解而拇</strong>：放开防御，让记录见光，信任自然来</li><li><strong>六五 → 存在即是解</strong>：系统演化本身，就是解</li><li><strong>上六 → 射隼</strong>：厚积薄发的那一刻，靠的不是那一击，是前面的每一次 commit</li></ul><blockquote><p><strong>AI 时代最稀缺的不是速度，而是站得稳的人。</strong> 速度是雷，是震；站得稳是水，是坎。解卦告诉我们：雷再快，也要落在水上——动要稳，快要有根。</p></blockquote><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：屯（第三卦）、蹇（第三十九卦）</li><li>屯与解：屯是险压着动（困难初生，宜扎根），解是动越过险（困难化解，宜行动）——同一种结构，换了个方向，就从难变成了解</li><li>蹇与解：蹇是水山（险在山上，进退两难），解是雷水（动越过险，化险为夷）——序卦：「解者缓也」；蹇难之后，终须解开</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/bian-yi">变易</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>',22))])}}});export{b as __pageData,y as default};
